function Get-FileSizeKB {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory, ValueFromPipeline, ValueFromPipelineByPropertyName)]
    [Alias('FullName')]
    [string[]]$Path
  )
  begin   { $total = 0 }
  process {                                  # once per pipeline item
    foreach ($p in $Path) {
      $kb = [math]::Round((Get-Item $p).Length / 1KB, 1)
      $total += $kb
      [pscustomobject]@{ File = Split-Path $p -Leaf; KB = $kb }
    }
  }
  end     { Write-Verbose "total: $total KB" }
}
Get-ChildItem $PSHOME -Filter *.json | Get-FileSizeKB -Verbose   # FullName binds to Path
Get-FileSizeKB -Path (Join-Path $PSHOME 'pwsh.dll')              # direct call

