$count = 0
function Bump { $count++; "inside: $count" }        # creates a LOCAL copy
Bump; "outside: $count"                             # inside: 1 / outside: 0
function BumpScript { $script:count++ }
BumpScript; "outside: $count"                       # outside: 1
$n = 20000
$slow = Measure-Command { $a = @(); foreach ($i in 1..$n) { $a += $i } }
$fast = Measure-Command { $a = foreach ($i in 1..$n) { $i } }
$slow.TotalMilliseconds -gt $fast.TotalMilliseconds * 10   # True
$cmdlet = Measure-Command { 1..$n | ForEach-Object { $_ * 2 } }
$stmt   = Measure-Command { foreach ($i in 1..$n) { $i * 2 } }
$cmdlet.TotalMilliseconds -gt $stmt.TotalMilliseconds      # True
(1..$n).Where({ $_ % 2 -eq 0 }, 'First', 3) -join ','      # 2,4,6  (stops early)
